package ext

import (
 \"testing\"
 \"gopkg.in/yaml.v2\"
)

func TestRuleSegmentForms(t *testing.T) {
 for _, tc := range []struct{ input string; keys []string; operator string }{
  {\"segment: foo\", []string{\"foo\"}, \"OR_SEGMENT_OPERATOR\"},
  {\"segment:\\n  keys: [foo, bar]\\n  operator: AND_SEGMENT_OPERATOR\", []string{\"foo\", \"bar\"}, \"AND_SEGMENT_OPERATOR\"},
  {\"segment:\\n  keys: [foo]\\n  operator: AND_SEGMENT_OPERATOR\", []string{\"foo\"}, \"OR_SEGMENT_OPERATOR\"},
 } {
  var rule Rule
  if err := yaml.Unmarshal([]byte(tc.input), &rule); err "'!= nil { t.Fatalf("%q: %v", tc.input, err) }
  keys, operator, err := rule.Segment.parts()
  if err != nil { t.Fatal(err) }
  if len(keys) != len(tc.keys) || operator != tc.operator { t.Fatalf("%q: keys=%v operator=%s", tc.input, keys, operator) }
 }
 for _, input := range []string{"segment: {}", "segment: []", "segment: 42", "segment: '"''\", \"segment:\\n  keys: [foo, bar]\", \"segment:\\n  keys: [foo, bar]\\n  operator: BAD\"} {
  var rule Rule
  if err := yaml.Unmarshal([]byte(input), &rule); err == nil { t.Errorf(\"accepted %q\", input) }
 }
}
EOF
go test ./internal/ext -run TestRuleSegmentForms -count=1"

